"""Small dependency-free observability UI served directly by FastAPI."""

from __future__ import annotations

DASHBOARD_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PETLIBRO Local Relay</title><style>
:root{color-scheme:dark;--bg:#0e1319;--panel:#17212c;--panel-2:#101923;--line:#2c3a49;--text:#eef4f8;--muted:#91a2b3;--ok:#35bf82;--warn:#f0ad4e;--bad:#ed6b6b;--unknown:#8b98a6;--focus:#4b8fc4}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}header{padding:17px 24px 13px;border-bottom:1px solid var(--line);background:rgba(14,19,25,.98);position:sticky;top:0;z-index:5;backdrop-filter:blur(10px)}.head-row{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}h1{font-size:21px;line-height:1.15;margin:0 0 11px}.build-meta{font-size:12px;color:var(--muted);white-space:nowrap}.status{display:flex;gap:8px;flex-wrap:wrap}.badge{display:inline-flex;gap:6px;align-items:center;border-radius:999px;padding:4px 9px;font-weight:600;font-size:12px;background:#24313e;color:var(--muted)}.badge::before{content:"●";font-size:10px}.state-online{color:var(--ok)}.state-connecting{color:var(--warn)}.state-offline{color:var(--bad)}.state-unknown{color:var(--unknown)}nav{display:flex;gap:5px;overflow-x:auto;padding:11px 20px;border-bottom:1px solid var(--line)}button,select,input{font:inherit}button{background:#263646;color:var(--text);border:1px solid #34485b;border-radius:6px;padding:7px 11px;cursor:pointer}button:hover{border-color:#5798c9}button.active{background:#3e7fae;border-color:#5da5d8}.raw-button{padding:4px 8px;font-size:12px;background:#1e2a35}.tab-section{display:none}.tab-section.active{display:block}main{max-width:1450px;margin:0 auto;padding:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(265px,1fr));gap:13px}.grid.wide{grid-template-columns:repeat(auto-fit,minmax(360px,1fr))}.card{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:15px;min-width:0}.card h2{font-size:15px;margin:0 0 11px}.card h3{font-size:13px;margin:14px 0 8px;color:var(--muted)}.card-head{display:flex;align-items:center;justify-content:space-between;gap:9px;margin-bottom:10px}.card-head h2{margin:0}.kv{display:grid;grid-template-columns:minmax(105px,1fr) auto;gap:7px 15px;align-items:baseline}.kv dt{color:var(--muted)}.kv dd{margin:0;font-weight:600;text-align:right;max-width:260px;overflow-wrap:anywhere}.muted{color:var(--muted)}.accent{color:var(--text)}.warning-value{color:var(--warn)}.ok-value{color:var(--ok)}.section-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:0 0 13px}.section-title h2{margin:0;font-size:18px}.metric-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(145px,1fr));gap:10px;margin:13px 0}.metric{background:var(--panel-2);border:1px solid var(--line);border-radius:7px;padding:10px}.metric .label{color:var(--muted);font-size:12px}.metric .number{font-size:20px;font-weight:700;margin-top:3px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:7px}table{width:100%;border-collapse:collapse;min-width:620px}th,td{padding:9px 10px;text-align:left;border-bottom:1px solid var(--line);vertical-align:middle}th{font-size:11px;letter-spacing:.045em;text-transform:uppercase;color:var(--muted);background:#121b24}tr:last-child td{border-bottom:0}.topic{font:12px ui-monospace,SFMono-Regular,Menlo,monospace;overflow-wrap:anywhere}.empty{padding:18px;color:var(--muted);text-align:center}.timeline{border-left:2px solid var(--line);margin:4px 0 0 7px;padding-left:16px}.timeline-item{position:relative;padding:0 0 13px}.timeline-item::before{content:"";position:absolute;width:9px;height:9px;border-radius:50%;background:var(--unknown);left:-22px;top:5px}.timeline-item.online::before{background:var(--ok)}.timeline-item.connecting::before{background:var(--warn)}.timeline-item.offline::before{background:var(--bad)}.timeline-time{font:12px ui-monospace,SFMono-Regular,Menlo,monospace;color:var(--muted);margin-right:8px}.timeline-label{font-weight:700}.details{margin-top:10px}.details summary{cursor:pointer;color:#a9d3ef;font-size:12px}.details pre{margin:8px 0 0;padding:10px;background:#0b1016;border:1px solid var(--line);border-radius:6px;white-space:pre-wrap;overflow:auto;max-height:300px;font:12px ui-monospace,SFMono-Regular,Menlo,monospace}.rssi{font-weight:700}.rssi.excellent{color:var(--ok)}.rssi.good{color:#9ed48d}.rssi.weak{color:var(--warn)}.rssi.poor{color:var(--bad)}.toolbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-bottom:10px}.toolbar label{color:var(--muted);font-size:12px}.toolbar select,.toolbar input{background:#101923;border:1px solid var(--line);border-radius:5px;color:var(--text);padding:6px 8px}.toolbar input{min-width:190px}.log-console{height:60vh;min-height:330px;overflow:auto;background:#090d12;border:1px solid var(--line);border-radius:7px;padding:9px;font:12px/1.55 ui-monospace,SFMono-Regular,Menlo,monospace}.log-line{display:grid;grid-template-columns:92px 70px 115px 1fr;gap:8px;white-space:pre-wrap;overflow-wrap:anywhere}.log-time{color:var(--muted)}.log-level{font-weight:700}.log-level.WARNING{color:var(--warn)}.log-level.ERROR,.log-level.CRITICAL{color:var(--bad)}.log-component{color:#91c8ec}.hidden{display:none!important}dialog{width:min(760px,92vw);color:var(--text);background:var(--panel);border:1px solid var(--line);border-radius:9px;padding:0}dialog::backdrop{background:rgba(0,0,0,.6)}.modal-head{display:flex;justify-content:space-between;align-items:center;padding:12px 14px;border-bottom:1px solid var(--line)}.modal-head h2{margin:0;font-size:15px}.modal-content{padding:14px;max-height:70vh;overflow:auto}.modal-content pre{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;font:12px ui-monospace,SFMono-Regular,Menlo,monospace}@media(max-width:650px){header{padding:14px}.head-row{display:block}.build-meta{margin-top:9px}main{padding:13px}.grid,.grid.wide{grid-template-columns:1fr}.kv{grid-template-columns:1fr auto}.log-line{grid-template-columns:75px 63px 1fr}.log-component{display:none}.toolbar input{min-width:130px}}
</style></head><body>
<header><div class="head-row"><div><h1>PETLIBRO Local Relay</h1><div class="status" id="header-badges">Loading…</div></div><div class="build-meta" id="build-meta">—</div></div></header>
<nav id="tabs" aria-label="Dashboard sections"></nav>
<main>
<section id="Overview" class="tab-section active"></section><section id="Cloud" class="tab-section"></section><section id="Devices" class="tab-section"></section><section id="Queues" class="tab-section"></section><section id="State" class="tab-section"></section><section id="NTP" class="tab-section"></section>
<section id="Logs" class="tab-section"><div class="section-title"><h2>Logs</h2><span class="muted">Live SSE stream</span></div><div class="toolbar"><label>Level <select id="log-level"><option value="">All</option><option>DEBUG</option><option>INFO</option><option>WARNING</option><option>ERROR</option></select></label><label>Component <select id="log-component"><option value="">All</option></select></label><label>Device <select id="log-device"><option value="">All</option></select></label><label>CMD <select id="log-cmd"><option value="">All</option></select></label><label>Search <input id="log-search" type="search" placeholder="Search logs"></label><button id="log-pause" type="button">Pause</button><button id="log-scroll" type="button">Auto-scroll: On</button></div><div class="log-console" id="logs-console" aria-live="polite"></div></section>
<section id="System" class="tab-section"></section>
</main>
<dialog id="raw-modal"><div class="modal-head"><h2 id="raw-title">Raw JSON</h2><button id="raw-close" type="button">Close</button></div><div class="modal-content"><pre id="raw-content"></pre></div></dialog>
<script>
const TAB_NAMES=['Overview','Cloud','Devices','Queues','State','NTP','Logs','System'];
const runtime={active:'Overview',raw:new Map(),rawId:0,logs:[],paused:false,autoScroll:true,logEventSource:null};
const byId=id=>document.getElementById(id);
const escapeHtml=value=>String(value??'—').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const fetchJson=async path=>{const response=await fetch(path);if(!response.ok)throw new Error(`HTTP ${response.status}`);return response.json()};
function epochSeconds(value){if(value===null||value===undefined||value==='')return null;const number=Number(value);if(!Number.isFinite(number))return null;return number>100000000000?number/1000:number}
function formatDuration(seconds){if(seconds===null||seconds===undefined||!Number.isFinite(Number(seconds)))return '—';let value=Math.max(0,Math.floor(Number(seconds)));const days=Math.floor(value/86400);value%=86400;const hours=Math.floor(value/3600);value%=3600;const minutes=Math.floor(value/60);value%=60;const parts=[];if(days)parts.push(`${days}d`);if(hours||days)parts.push(`${hours}h`);if(minutes||hours||days)parts.push(`${minutes}m`);parts.push(`${value}s`);return parts.join(' ')}
function formatAge(timestamp){const seconds=epochSeconds(timestamp);return seconds===null?'—':formatDuration(Date.now()/1000-seconds)+' ago'}
function formatTimestamp(timestamp){const seconds=epochSeconds(timestamp);if(seconds===null)return '—';return new Date(seconds*1000).toLocaleString(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit',year:'numeric',month:'short',day:'2-digit'})}
function formatTime(timestamp){const seconds=epochSeconds(timestamp);return seconds===null?'—':new Date(seconds*1000).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
function formatPercent(value){return value===null||value===undefined?'—':`${Math.round(Number(value)*100)} %`}
function formatBoolean(value){return value===true?'Enabled':value===false?'Disabled':'—'}
function formatBytes(value){if(value===null||value===undefined)return '—';const units=['B','KB','MB','GB','TB'];let size=Number(value),index=0;while(size>=1024&&index<units.length-1){size/=1024;index++}return `${size.toFixed(index?1:0)} ${units[index]}`}
function statusClass(state){const normalized=String(state||'UNKNOWN').toUpperCase();if(normalized==='ONLINE'||normalized==='RUNNING'||normalized==='ACTIVE')return 'state-online';if(normalized.includes('CONNECTING')||normalized==='PENDING')return 'state-connecting';if(normalized==='DISCONNECTED'||normalized==='OFFLINE'||normalized==='ERROR')return 'state-offline';return 'state-unknown'}
function statusBadge(state,label){const text=String(state||'UNKNOWN').replaceAll('_',' ');return `<span class="badge ${statusClass(state)}">${escapeHtml(label||text)}${label?`: ${escapeHtml(text)}`:''}</span>`}
function rawButton(value,label='View raw JSON'){const id=String(++runtime.rawId);runtime.raw.set(id,value);return `<button type="button" class="raw-button" data-raw-id="${id}">${escapeHtml(label)}</button>`}
function bindRawButtons(){document.querySelectorAll('[data-raw-id]').forEach(button=>{button.onclick=()=>openRaw(runtime.raw.get(button.dataset.rawId))})}
function openRaw(value){byId('raw-content').textContent=JSON.stringify(value,null,2);byId('raw-modal').showModal()}
function card(title,content,extra=''){return `<article class="card">${extra?`<div class="card-head"><h2>${escapeHtml(title)}</h2>${extra}</div>`:`<h2>${escapeHtml(title)}</h2>`}${content}</article>`}
function kv(rows){return `<dl class="kv">${rows.map(([key,value,klass])=>`<dt>${escapeHtml(key)}</dt><dd${klass?` class="${escapeHtml(klass)}"`:''}>${value}</dd>`).join('')}</dl>`}
function metric(label,value,klass=''){return `<div class="metric"><div class="label">${escapeHtml(label)}</div><div class="number ${escapeHtml(klass)}">${escapeHtml(value)}</div></div>`}
function table(headers,rows,empty='No data'){if(!rows.length)return `<div class="empty">${escapeHtml(empty)}</div>`;return `<div class="table-wrap"><table><thead><tr>${headers.map(header=>`<th>${escapeHtml(header)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function scalar(value){if(value===true||value===false)return escapeHtml(formatBoolean(value));if(value===null||value===undefined)return '—';if(typeof value==='object')return '<span class="muted">Object</span>';return escapeHtml(value)}
function payloadMsgId(payload){return payload&&typeof payload==='object'&&typeof payload.msgId==='string'?payload.msgId:'—'}
function rssiMarkup(value){if(value===null||value===undefined)return '—';const rssi=Number(value);const quality=rssi>-50?'excellent':rssi>-60?'good':rssi>-70?'weak':'poor';const label=rssi>-50?'excellent':rssi>-60?'good':rssi>-70?'weak':'poor';return `<span class="rssi ${quality}">${escapeHtml(`${rssi} dBm · ${label}`)}</span>`}
function setupTabs(){byId('tabs').innerHTML=TAB_NAMES.map(name=>`<button type="button" data-tab="${name}" class="${runtime.active===name?'active':''}">${escapeHtml(name)}</button>`).join('');document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>showTab(button.dataset.tab));}
function showTab(name){runtime.active=name;TAB_NAMES.forEach(tab=>byId(tab).classList.toggle('active',tab===name));setupTabs();refresh()}
function renderHeader(status,system){const device=status.device;const deviceState=device&&Number(device.age_seconds)<90?'ONLINE':device?'STALE':'UNKNOWN';byId('header-badges').innerHTML=[statusBadge('RUNNING','Relay'),statusBadge(status.local_mqtt.connected?'ONLINE':'OFFLINE','Local MQTT'),statusBadge(status.upstream.state,'PETLIBRO'),statusBadge(deviceState,deviceState==='ONLINE'?'PLAF203':'PLAF203')].join('');const seen=device?`Last seen ${formatAge(device.last_seen_at)}`:'Waiting for feeder';byId('build-meta').textContent=`Uptime ${formatDuration(status.relay.uptime_seconds)} · ${system.version} · ${system.git_commit} · ${seen}`}
function renderOverview(status,queues){const upstream=status.upstream,counters=upstream.counters||{},q1=queues.device_to_cloud,q2=queues.cloud_to_device,shadow=status.state_shadow,responder=status.local_responder;const queuePending=Number(q1.pending)+Number(q2.pending);byId('Overview').innerHTML=`<div class="section-title"><h2>Overview</h2><span>${statusBadge(status.relay.status,'Relay')}</span></div><div class="grid wide">${card('Relay',kv([['Status',escapeHtml('Running'),'ok-value'],['Mode',escapeHtml(status.relay.mode==='PURE_PIPE'?'Pure pipe':'Local fallback')],['Uptime',escapeHtml(formatDuration(status.relay.uptime_seconds))],['Local responder',escapeHtml(formatBoolean(status.relay.local_responder_enabled))]]))}${card('Upstream',kv([['Status',statusBadge(upstream.state)],['Last online',escapeHtml(formatTimestamp(upstream.last_connack_0))],['Last disconnect',escapeHtml(formatAge(upstream.last_disconnect))],['Current session',escapeHtml(formatDuration(upstream.current_online_duration_seconds))],['Previous session',escapeHtml(formatDuration(upstream.previous_session_duration_seconds))],['Availability 15m',escapeHtml(formatPercent(upstream.availability?.['15m']))],['Availability 1h',escapeHtml(formatPercent(upstream.availability?.['1h']))],['Availability 24h',escapeHtml(formatPercent(upstream.availability?.['24h']))]]))}${card('Queues',kv([['Device → Cloud',`${escapeHtml(q1.pending)} pending`,q1.pending?'warning-value':'ok-value'],['Cloud → Device',`${escapeHtml(q2.pending)} pending`,q2.pending?'warning-value':'ok-value'],['Oldest message',escapeHtml(formatDuration(Math.max(Number(q1.oldest_age_seconds||0),Number(q2.oldest_age_seconds||0))))]]),queuePending?statusBadge('PENDING','Backlog'):'')}${card('State shadow',kv([['Reported state',`${escapeHtml(shadow.reported)} values`],['Cloud desired',`${escapeHtml(shadow.desired)} values`],['Raw cached messages',escapeHtml(shadow.raw_messages)],['Feeding plan',shadow.feeding_plan_cached?'<span class="ok-value">Cached ✓</span>':'<span class="muted">Not cached</span>']]))}${card('Local responder',kv([['Global',escapeHtml(formatBoolean(responder.enabled))],['NTP',escapeHtml(formatBoolean(responder.ntp_enabled))],['Config',escapeHtml(formatBoolean(responder.config_enabled))],['Feeding plan',escapeHtml(formatBoolean(responder.feeding_plan_enabled))],['Local responses',escapeHtml(responder.counters?.local_responses||0)],['Cache hits',escapeHtml(responder.counters?.cache_hits||0)],['Cache misses',escapeHtml(responder.counters?.cache_misses||0)],['Suppressed responses',escapeHtml(responder.counters?.suppressed_late_cloud_responses||0)]]))}</div>`;bindRawButtons()}
function eventPresentation(event){const kind=String(event.kind||'');if(kind==='upstream_online')return ['ONLINE','online'];if(kind==='upstream_restored')return ['RESTORED','online'];if(kind==='upstream_session_lost')return ['SESSION LOST','offline'];if(kind==='upstream_connect_attempt')return ['MQTT CONNECTING','connecting'];if(kind==='upstream_retry_failed'||kind==='upstream_tcp_connect_failed'||kind==='upstream_connack_refused')return ['RETRY FAILED','connecting'];return [kind.replaceAll('_',' ').toUpperCase(),'unknown']}
function renderCloud(cloud){const up=cloud.upstream,c=up.counters||{};const events=cloud.events.filter(event=>String(event.kind).startsWith('upstream')).reverse();byId('Cloud').innerHTML=`<div class="section-title"><h2>Cloud</h2>${statusBadge(up.state)}</div><div class="grid wide"><article class="card"><h2>Availability</h2><div class="metric-grid">${metric('15 minutes',formatPercent(up.availability?.['15m']))}${metric('1 hour',formatPercent(up.availability?.['1h']))}${metric('24 hours',formatPercent(up.availability?.['24h']))}</div><h3>Sessions</h3>${kv([['Current session',escapeHtml(formatDuration(up.current_online_duration_seconds))],['Previous session',escapeHtml(formatDuration(up.previous_session_duration_seconds))],['Average',escapeHtml(formatDuration(up.average_session_duration_seconds))],['Minimum',escapeHtml(formatDuration(up.minimum_session_duration_seconds))],['Maximum',escapeHtml(formatDuration(up.maximum_session_duration_seconds))]])}</article><article class="card"><h2>Connection counters</h2><div class="metric-grid">${metric('Connect attempts',c.connect_attempts||0)}${metric('Successful CONNACK',c.connack_success||0,'ok-value')}${metric('CONNACK timeouts',c.connack_timeouts||0,'warning-value')}${metric('CONNACK refused',c.connack_refused||0)}${metric('Sessions lost',c.sessions_lost||0,'warning-value')}${metric('Reconnect failures',c.reconnect_failures||0,'warning-value')}${metric('TCP failures',c.tcp_connect_failures||0,'warning-value')}</div></article></div>${card('Recent upstream timeline',events.length?`<div class="timeline">${events.map(event=>{const [label,kind]=eventPresentation(event);return `<div class="timeline-item ${kind}"><span class="timeline-time">${escapeHtml(formatTime(event.timestamp))}</span><span class="timeline-label">${escapeHtml(label)}</span><div class="muted">${escapeHtml(event.message)}</div></div>`}).join('')}</div>`:'<div class="empty">No upstream events recorded yet.</div>')}`}
function renderDevices(devices){const active=devices.active;const activeCard=active?card('PLAF203',kv([['Status',statusBadge(active.status)],['Device ID',escapeHtml(active.client_id)],['IP',escapeHtml(active.ip)],['Firmware',escapeHtml(active.firmware)],['RSSI',rssiMarkup(active.rssi)],['Last heartbeat',escapeHtml(formatAge(active.last_heartbeat_ts))],['Last seen',escapeHtml(formatAge(active.last_seen_at))],['Username',escapeHtml(active.username)],['Active TTL remaining',escapeHtml(formatDuration(active.ttl_remaining_seconds))]]),statusBadge('ACTIVE')):card('Active device','<div class="empty">Waiting for the first feeder connection.</div>');const rows=devices.candidates.map(item=>`<tr><td>${escapeHtml(item.client_id)}</td><td>${escapeHtml(item.username)}</td><td>${escapeHtml(formatTimestamp(item.first_seen_at))}</td><td>${escapeHtml(formatAge(item.last_seen_at))}</td><td>${statusBadge(item.status)}</td></tr>`);byId('Devices').innerHTML=`<div class="section-title"><h2>Devices</h2><span class="muted">One active device per relay</span></div><div class="grid wide">${activeCard}${card('Candidates',table(['Device ID','Username','First seen','Last seen','Status'],rows,'No candidate devices.'))}</div>`}
function queueRows(queue){return queue.messages.map(item=>`<tr><td>${escapeHtml(formatTime(item.created_at))}</td><td>${escapeHtml(queue.direction==='local-to-upstream'?'Device → Cloud':'Cloud → Device')}</td><td>${escapeHtml(item.cmd||'—')}</td><td>${escapeHtml(payloadMsgId(item.payload))}</td><td>${escapeHtml(formatDuration(item.age_seconds))}</td><td>${escapeHtml(item.replay_policy)}</td><td>${statusBadge('PENDING')}</td><td><details class="details"><summary>Topic</summary><div class="topic">${escapeHtml(item.topic)}</div></details> ${rawButton(item.payload,'View JSON')}</td></tr>`)}
function queueCard(title,queue){return card(title,`<div class="metric-grid">${metric('Pending',queue.pending,queue.pending?'warning-value':'ok-value')}${metric('Oldest',formatDuration(queue.oldest_age_seconds))}${metric('Newest',formatDuration(queue.newest_age_seconds))}</div>${table(['Time','Direction','CMD','Msg ID','Age','Policy','Status','Debug'],queueRows(queue),'Queue is empty.')}`,queue.pending?statusBadge('PENDING','Backlog'):statusBadge('ONLINE','Clear'))}
function renderQueues(queues){byId('Queues').innerHTML=`<div class="section-title"><h2>Queues</h2><span class="muted">Durable SQLite queues</span></div><div class="grid wide">${queueCard('Device → Cloud',queues.device_to_cloud)}${queueCard('Cloud → Device',queues.cloud_to_device)}</div>`;bindRawButtons()}
function stateRows(rows){return rows.map(item=>`<tr><td>${escapeHtml(item.key)}</td><td>${scalar(item.value)}</td><td>${escapeHtml(formatTimestamp(item.updated_at))}</td><td>${escapeHtml(formatAge(item.updated_at))}</td><td>${typeof item.value==='object'?rawButton(item.value,'View JSON'):''}</td></tr>`)}
function renderState(state){const plan=state.feeding_plans;const rawRows=state.raw_messages.map(item=>`<tr><td class="topic">${escapeHtml(item.topic)}</td><td>${escapeHtml(item.cmd||'—')}</td><td>${escapeHtml(formatTimestamp(item.updated_at))}</td><td>${rawButton(item.payload,'View JSON')}</td></tr>`);byId('State').innerHTML=`<div class="section-title"><h2>State shadow</h2><span class="muted">Last-known values only</span></div><div class="grid wide">${card('Reported state',table(['Key','Value','Updated','Age','Debug'],stateRows(state.reported),'No reported state.'))}${card('Cloud desired',table(['Key','Value','Updated','Age','Debug'],stateRows(state.desired),'No cloud desired state.'))}${card('Feeding plan',kv([['Status',plan.complete?'<span class="ok-value">Cached ✓</span>':'<span class="muted">Not cached</span>'],['Updated',escapeHtml(formatTimestamp(plan.updated_at))],['Source message ID',escapeHtml(plan.source_msg_id)],['Plans',escapeHtml(plan.plans?.length||0)]] )+(plan.complete?`<div class="details">${rawButton(plan.plans,'View raw JSON')}</div>`:'') )}</div>${card('Raw messages',table(['Topic','CMD','Updated','Debug'],rawRows,'No raw messages cached.'))}`;bindRawButtons()}
function renderNtp(ntp,status){const responder=status.local_responder;const timezone=responder.device_timezone||'—';byId('NTP').innerHTML=`<div class="section-title"><h2>NTP Observer</h2>${statusBadge(ntp.local_fallback_enabled?'ONLINE':'DISABLED','Local fallback')}</div><div class="grid wide">${card('NTP observer',kv([['Last request',escapeHtml(formatTimestamp(ntp.last_request?.updated_at))],['Trigger',escapeHtml(String(ntp.trigger||'').replaceAll('_',' '))],['Requests observed',escapeHtml(ntp.requests_observed)],['Cloud responses',escapeHtml(ntp.cloud_ntp_sync_responses)],['Local responses',escapeHtml(ntp.local_ntp_responses)],['Local fallback',escapeHtml(formatBoolean(ntp.local_fallback_enabled))]]))}${card('Timezone and DST',kv([['Timezone',escapeHtml(timezone)],['Current offset','—'],['DST','—'],['Next transition','—']])+'<div class="muted" style="margin-top:10px">DST fields are shown when a NTP_SYNC payload provides them.</div>')}</div>${card('NTP debug',`<div class="toolbar">${ntp.last_request?rawButton(ntp.last_request.payload,'View request raw JSON'):''}${ntp.last_ntp_sync?rawButton(ntp.last_ntp_sync.payload,'View response raw JSON'):''}</div>`)}`;bindRawButtons()}
function renderSystem(system,status){const dbRows=system.databases.map(item=>`<tr><td>${escapeHtml(item.name)}</td><td>${escapeHtml(formatBytes(item.size_bytes))}</td><td class="topic">${escapeHtml(item.path)}</td></tr>`);const runtimeData=system.runtime||{},memory=runtimeData.memory||{},disk=runtimeData.disk||{};byId('System').innerHTML=`<div class="section-title"><h2>System</h2><span class="muted">Local process diagnostics</span></div><div class="grid wide">${card('Application',kv([['Version',escapeHtml(system.version)],['Commit',escapeHtml(system.git_commit)],['Python',escapeHtml(system.python_version)],['Hostname',escapeHtml(system.hostname)],['Uptime',escapeHtml(formatDuration(status.relay.uptime_seconds))]]))}${card('Runtime',kv([['CPU load (1m)',escapeHtml(runtimeData.cpu_load_1m===null||runtimeData.cpu_load_1m===undefined?'—':Number(runtimeData.cpu_load_1m).toFixed(2))],['Memory',memory.total_bytes?escapeHtml(`${formatBytes(memory.used_bytes)} / ${formatBytes(memory.total_bytes)}`):'—'],['Disk',disk.total_bytes?escapeHtml(`${formatBytes(disk.used_bytes)} / ${formatBytes(disk.total_bytes)}`):'—']]))}${card('Storage',table(['Database','Size','Path'],dbRows,'No database metadata.'))}</div>`}
function initializeLogControls(){['log-level','log-component','log-device','log-cmd','log-search'].forEach(id=>byId(id).addEventListener('input',applyLogFilters));byId('log-pause').onclick=()=>{runtime.paused=!runtime.paused;byId('log-pause').textContent=runtime.paused?'Resume':'Pause';if(!runtime.paused)renderLogLines()};byId('log-scroll').onclick=()=>{runtime.autoScroll=!runtime.autoScroll;byId('log-scroll').textContent=`Auto-scroll: ${runtime.autoScroll?'On':'Off'}`}}
function logFilters(){return {level:byId('log-level').value,component:byId('log-component').value,device:byId('log-device').value,cmd:byId('log-cmd').value,search:byId('log-search').value.toLowerCase()}}
function matchesLog(item){const filters=logFilters();return (!filters.level||item.level===filters.level)&&(!filters.component||item.component===filters.component)&&(!filters.device||item.device_id===filters.device)&&(!filters.cmd||item.cmd===filters.cmd)&&(!filters.search||`${item.message} ${item.component} ${item.device_id||''} ${item.cmd||''}`.toLowerCase().includes(filters.search))}
function addFilterOption(selectId,value){if(!value)return;const select=byId(selectId);if(Array.from(select.options).some(option=>option.value===value))return;const option=document.createElement('option');option.value=value;option.textContent=value;select.append(option)}
function appendLog(item){if(runtime.logs.some(existing=>existing.sequence===item.sequence))return;runtime.logs.push(item);if(runtime.logs.length>1000)runtime.logs.shift();addFilterOption('log-component',item.component);addFilterOption('log-device',item.device_id);addFilterOption('log-cmd',item.cmd);if(!runtime.paused)renderLogLines()}
function renderLogLines(){const consoleElement=byId('logs-console');consoleElement.textContent='';runtime.logs.filter(matchesLog).forEach(item=>{const line=document.createElement('div');line.className='log-line';line.dataset.level=item.level;line.dataset.component=item.component;line.dataset.device=item.device_id||'';line.dataset.cmd=item.cmd||'';line.innerHTML=`<span class="log-time"></span><span class="log-level"></span><span class="log-component"></span><span class="log-message"></span>`;line.querySelector('.log-time').textContent=new Date(item.timestamp*1000).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit',second:'2-digit',fractionalSecondDigits:3});const level=line.querySelector('.log-level');level.textContent=item.level;level.classList.add(item.level);line.querySelector('.log-component').textContent=item.component;line.querySelector('.log-message').textContent=item.message;consoleElement.append(line)});if(runtime.autoScroll)consoleElement.scrollTop=consoleElement.scrollHeight}
function applyLogFilters(){renderLogLines()}
async function loadInitialLogs(){const response=await fetchJson('/api/logs?limit=500');response.entries.forEach(appendLog)}
function startLogStream(){if(runtime.logEventSource)return;runtime.logEventSource=new EventSource('/api/logs/stream');runtime.logEventSource.addEventListener('log',event=>appendLog(JSON.parse(event.data)));runtime.logEventSource.onerror=()=>{runtime.logEventSource?.close();runtime.logEventSource=null;setTimeout(startLogStream,3000)}}
async function refresh(){try{const [status,system]=await Promise.all([fetchJson('/api/status'),fetchJson('/api/system')]);renderHeader(status,system);if(runtime.active==='Overview'){const queues=await fetchJson('/api/queues?limit=1');renderOverview(status,queues)}else if(runtime.active==='Cloud')renderCloud(await fetchJson('/api/cloud'));else if(runtime.active==='Devices')renderDevices(await fetchJson('/api/devices'));else if(runtime.active==='Queues')renderQueues(await fetchJson('/api/queues?limit=100'));else if(runtime.active==='State')renderState(await fetchJson('/api/state'));else if(runtime.active==='NTP')renderNtp(await fetchJson('/api/ntp'),status);else if(runtime.active==='System')renderSystem(system,status)}catch(error){byId('header-badges').innerHTML=statusBadge('ERROR','Dashboard');console.error(error)}}
byId('raw-close').onclick=()=>byId('raw-modal').close();setupTabs();initializeLogControls();loadInitialLogs().catch(console.error);startLogStream();refresh();setInterval(refresh,3000);
</script></body></html>"""
